// CHART-TYPE NAMES IN THE OTHER TIER 1 LANGUAGES.
//
// One table, three readers: a host DISPLAYS a chart type to a reader in their language, a reader's TYPED request names a
// chart type in their language ("como gráfico de barras", "als Sankey-Diagramm"), and the chooser's type-ahead filter
// finds "Balken" among the types. Keyed by the catalogue's English name; one name per type per language; every name is
// distinct within its language, so a name read back resolves to exactly one type.
//
// The server keeps a GENERATED copy of the block between the parity markers, and a parity test fails when the two differ:
// edit the names here, then regenerate the copy.
//
// READING A TYPED NAME (chartNameFromLocalized): the text is compared folded - lower case, accents removed, whitespace
// collapsed - against every language's names at once, because the language a reader types is not the one their host
// reports. A name that two languages use for DIFFERENT types reads as nothing rather than as a guess.

/** The languages of the table, in its order. */
export const CHART_NAME_LANGUAGES: readonly string[] = [
    "nl", "de", "fr", "es", "pt", "it", "pl", "cs", "sk", "sv", "da", "nb", "fi", "hu", "tr", "ro", "hr", "id", "vi",
    "ru", "uk", "el", "zh", "ja", "ko", "ar", "he", "hi", "th",
];

