/** The fold a typed name and a table name are compared in: lower case, Latin/Greek/Cyrillic accents removed,
 *  whitespace collapsed. */
export function foldChartName(s: string): string {
    return (s ?? "")
        .toLowerCase()
        .normalize("NFD")
        .replace(/[̀-ͯ]/g, "")
        .normalize("NFC")
        .replace(/\s+/g, " ")
        .trim();
}

/** A chart type's name in `lang`, or undefined when the type or the language has none. */
export function localizedChartName(englishName: string, lang: string): string | undefined {
    return LOCALIZED_CHART_NAMES[englishName]?.[lang];
}

/** Every language's name for a chart type (empty for an unknown type). */
export function localizedChartNames(englishName: string): ReadonlyArray<{ lang: string; name: string }> {
    const row = LOCALIZED_CHART_NAMES[englishName];
    return row ? Object.keys(row).map(lang => ({ lang, name: row[lang] })) : [];
}

let reverse: Map<string, string | null> | null = null;
function reverseIndex(): Map<string, string | null> {
    if (reverse) return reverse;
    const m = new Map<string, string | null>();
    for (const en of Object.keys(LOCALIZED_CHART_NAMES)) {
        const row = LOCALIZED_CHART_NAMES[en];
        for (const lang of Object.keys(row)) {
            const k = foldChartName(row[lang]);
            if (!k) continue;
            const had = m.get(k);
            // Two languages using one name for different types: ambiguous, so it reads as nothing.
            m.set(k, had === undefined || had === en ? en : null);
        }
    }
    return (reverse = m);
}

/** The catalogue's English name for a chart type named in any of the table's languages, or undefined. */
export function chartNameFromLocalized(text: string): string | undefined {
    const hit = reverseIndex().get(foldChartName(text));
    return hit ?? undefined;
}
